using NUnit.Framework;using UnityEngine;using UnityEditor;using EchoProtocol.Salvage;using EchoProtocol.Audio;
public sealed class SalvagePresentationTests{
[Test]public void GripPrefabAndDepthTestedMaterialsAreIncludedInResources(){var p=Resources.Load<SalvageGripVfx>("Salvage/Fx/SalvageGripVfx");Assert.That(p,Is.Not.Null);foreach(var m in new[]{p.BeamMaterial,p.OrbMaterial,p.VolumeMaterial}){Assert.That(m,Is.Not.Null);Assert.That(m.shader.isSupported,Is.True);Assert.That(m.renderQueue,Is.GreaterThanOrEqualTo(3000));}Assert.That(p.HumVolume,Is.LessThanOrEqualTo(.1f));Assert.That(Resources.Load<Material>("Salvage/Fx/SalvagePriceBubble"),Is.Null,"The reference pink object is not a currency UI bubble");}
[Test]public void ExistingSemanticSoundsResolveWithoutSubstitutingUnrelatedClips(){var c=Resources.Load<GameAudioCatalog>("GameAudioCatalog");foreach(var key in new[]{"energy_core/ambient_hum_loop","energy_core/deposit_into_sector_box","ui/inventory_pickup","ui/confirm","escape_endgame/countdown_start","escape_endgame/countdown_tick","escape_endgame/mission_failure","map_ambience/facility_room_tone_loop"})Assert.That(c.Find(key),Is.Not.Null,key);foreach(var key in new[]{"Grip","BrakeLatch","MetalContact","PlasticContact","OrganicContact","ScannerPulse","ScannerEmpty","ExtractionStart","Resonance"})Assert.That(Resources.Load<AudioClip>("Salvage/Audio/"+key),Is.Not.Null,key);}

}
